"""Preguntas adaptadas de exámenes oficiales; redacción y distractores revisados.
No se incluyen anuladas ni se trasladan datos municipales antiguos contra el manual.
"""
EXAMS=[]
URL25='https://institucional.cadiz.es/sites/default/files/tablon/archivos/CUESTIONARIO%20PRIMER%20Y%20SEGUNDO%20EJERCICIO%2012%20SUBALTERNOS%20OEP%202021%2C%202022%20Y%202023..pdf'
URL24='https://institucional.cadiz.es/sites/default/files/tablon/archivos/CUESTIONARIO%20DE%20EXAMEN%209%20SUBALTERNOS%2C%20OEP%202022%20ESTABILIZACI%C3%93N%2C%20CONCURSO-OPOSICI%C3%93N.pdf'
def exam(topic,num,prompt,correct,wrong,explanation,year=2025):
    assert len(wrong)==3
    EXAMS.append(dict(topic=topic,section='Examen oficial · adaptación',prompt=prompt,correct=correct,wrong=wrong,explanation=explanation,
      source={'kind':'exam-adapted','label':f'Examen de Cádiz · {"22/02/2025" if year==2025 else "17/09/2024"} (adaptada)',
      'reference':f'Pregunta {num}; contenido contrastado con el temario de septiembre de 2026','url':URL25 if year==2025 else URL24},format='examen',coverage=f'exam:{year}:{num}'))
exam(1,1,'¿Cuál no figura entre los valores superiores del artículo 1.1 de la Constitución?','Seguridad',['Igualdad','Justicia','Pluralismo político'],'Los cuatro valores son libertad, justicia, igualdad y pluralismo político. Seguridad jurídica aparece en el artículo 9.3.')
exam(1,2,'¿Qué artículo fundamenta la Constitución en la unidad indisoluble de la nación?','Artículo 2',['Artículo 1','Artículo 9','Artículo 10'],'El artículo 2 combina unidad, autonomía y solidaridad.')
exam(1,3,'¿Cómo se denomina el capítulo II del título VIII de la Constitución?','De la Administración Local',['De las Comunidades Autónomas','De los tratados internacionales','De las relaciones Gobierno-Cortes'],'Administración local: artículos 140–142; las comunidades autónomas están en capítulo III.')
exam(1,4,'Según el artículo 29.1, ¿cómo ejercen los españoles el derecho de petición?','Individual o colectivamente, por escrito y en forma legal',['Sólo individualmente y de forma verbal','Sólo colectivamente y de forma verbal','Únicamente por representante profesional'],'El derecho admite petición individual y colectiva, escrita, conforme a ley; para militares hay especialidad individual.')
exam(1,5,'¿En qué artículo está la participación en asuntos públicos mediante representantes elegidos por sufragio universal?','Artículo 23',['Artículo 13','Artículo 24','Artículo 10'],'La participación política se recoge en el 23, no en tutela judicial del 24.')
exam(1,6,'¿En qué estados puede suspenderse el derecho de huelga del artículo 28.2 según el artículo 55?','Excepción o sitio',['Sólo alarma','Sólo alarma y excepción','Nunca en ningún estado'],'El artículo 55 enumera huelga entre derechos suspendibles en excepción o sitio.')
exam(1,7,'¿Qué regla resulta contraria al artículo 9.3 de la Constitución?','Retroactividad de disposiciones sancionadoras desfavorables',['Publicidad de normas','Responsabilidad de poderes públicos','Prohibición de arbitrariedad'],'Se garantiza irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales.')
exam(3,8,'¿Cuál es la fecha de la Ley 31/1995 de Prevención de Riesgos Laborales?','8 de noviembre de 1995',['3 de abril de 1995','8 de octubre de 1995','3 de noviembre de 1995'],'El manual identifica Ley 31/1995, de 8 de noviembre.')
exam(3,9,'¿Qué define correctamente un riesgo grave e inminente?','Probable materialización inmediata con daño grave',['Lesión ya producida, sea cual sea su gravedad','Riesgo que nunca puede materializarse pronto','Sólo una enfermedad sin relación con trabajo'],'Importan probabilidad inmediata y gravedad; algunos daños aparecen después de exposición inmediata.')
exam(3,10,'¿Qué prioridad preventiva establece el artículo 15?','Protección colectiva antes que individual',['Protección individual antes que colectiva','Compensación económica antes que seguridad','Ignorar la evolución técnica'],'Las medidas colectivas tienen prioridad frente a EPI.')
exam(3,11,'¿Qué es un equipo de trabajo según la Ley 31/1995?','Máquina, aparato, instrumento o instalación utilizada en trabajo',['Sólo una prenda llevada como protección','Sólo una instalación fija de propiedad del trabajador','Sólo la ropa de uniforme'],'Equipo de trabajo no es lo mismo que EPI, llevado o sujetado para proteger.')
exam(3,12,'¿Cuál es el derecho central del trabajador en el artículo 14 de la Ley 31/1995?','Protección eficaz en seguridad y salud',['Reparar cualquier avería eléctrica sin formación','Pagar el coste de las medidas preventivas','Rechazar toda instrucción preventiva'],'La protección eficaz es derecho del trabajador y deber correlativo del empleador.')
exam(2,13,'¿Qué situación constituye discriminación directa por sexo?','Trato menos favorable por sexo frente a otra persona comparable',['Cualquier diferencia razonable sin relación con sexo','Sólo una disposición neutra con efecto desigual','Todo trato idéntico que elimina barreras'],'Directa: trato menos favorable por sexo; indirecta: criterio neutro con desventaja no justificada.')
exam(2,14,'¿Cómo se califica un trato desfavorable relacionado con embarazo o maternidad en LO 3/2007?','Discriminación directa por razón de sexo',['Discriminación indirecta exclusivamente','Acción positiva','Conducta siempre permitida por contrato'],'El artículo 8 lo califica de discriminación directa.')
exam(5,15,'¿Qué supuesto permite notificación no electrónica en la Ley 39/2015?','Comparecencia espontánea en OAMR solicitando entrega personal',['Cualquier obligado electrónico decide unilateralmente ignorar su obligación','Toda notificación debe ser verbal','Nunca cabe entrega directa por empleado público'],'La comparecencia espontánea con solicitud personal es excepción prevista; también entrega directa por eficacia en condiciones legales.')
exam(5,16,'¿Qué canal es preferente para notificaciones y obligatorio para quienes deban recibir por él?','Medios electrónicos',['Siempre llamada telefónica','Siempre correo ordinario sin constancia','Siempre entrega verbal'],'Artículo 41: preferencia electrónica y obligación para sujetos correspondientes.')
exam(5,17,'Si se practica válidamente una notificación por varios canales, ¿qué fecha prevalece?','La primera notificación practicada',['La última notificación practicada','La de redacción del correo de aviso','La elegida libremente por el receptor'],'Cuenta la primera practicada, no una simple preparación ni un aviso.')
exam(5,18,'Primer intento domiciliario a las 16:00 sin receptor. ¿Qué debe cumplir el segundo?','Dentro de tres días siguientes, antes de 15:00 y con margen mínimo de tres horas',['Dentro de dos días, siempre después de 15:00','A la misma hora cualquier día del mes','Dar por notificado sin otro trámite'],'Se repite una vez en franja distinta, antes/después de 15:00, con diferencia horaria mínima.')
exam(5,19,'Falta el aviso por correo de una notificación electrónica correctamente puesta a disposición. ¿Qué efecto tiene por sí sola esa falta?','No invalida la notificación',['Anula automáticamente el acto','Impide siempre cualquier efecto','Obliga siempre a notificar por fax'],'Aviso y notificación son distintos; ausencia del aviso no invalida por sí sola.')
exam(5,20,'¿Cuándo se entiende rechazada una notificación electrónica obligatoria o elegida sin acceso?','Tras diez días naturales desde puesta a disposición',['Tras diez días hábiles','Tras quince días naturales','Tras cuarenta y ocho horas hábiles'],'Artículo 43: diez días naturales sin acceso en supuestos indicados.')
exam(7,22,'¿Qué conjunto resume las funciones esenciales de un archivo?','Recibir, conservar y servir',['Recibir y modificar arbitrariamente','Destruir y divulgar todo','Archivar sin facilitar nunca consulta'],'Se conserva documentación y se sirve a gestión, derechos, investigación e información conforme a límites.')
exam(4,25,'¿Qué límites menciona el artículo 105 b) para acceso a archivos y registros?','Seguridad y defensa, averiguación de delitos e intimidad',['Sólo falta de espacio','Sólo preferencia del empleado','Ningún límite en ningún caso'],'La Constitución recoge esos límites, desarrollados en normas de acceso y protección de datos.')
exam(7,27,'¿Qué pareja está formada por documentos de decisión?','Acuerdo y resolución',['Acta y certificado','Oficio y notificación','Informe y dictamen'],'Pregunta 27 corregida en plantilla definitiva de marzo de 2025: acuerdo y resolución. Las otras parejas son constancia, transmisión y juicio.')
exam(4,32,'¿A quién puede facilitarse información particular de un procedimiento?','A interesados o representantes debidamente acreditados',['A cualquier vecino sin identificación','Sólo a quien publique su petición en redes','A cualquier persona por conocer el número de expediente'],'La información particular exige identidad y condición de interesado o representación.')
exam(4,33,'¿Qué presenta una persona cuando propone una idea para mejorar un servicio?','Sugerencia',['Recurso de alzada','Sanción','Certificación'],'Sugerencia busca mejora; queja expresa insatisfacción y recurso impugna acto.')
exam(4,39,'¿Cómo se llaman las oficinas que asisten a ciudadanos en presentación y registro?','Oficinas de asistencia en materia de registros',['Oficinas judiciales de recursos','Tribunales de registro general','Oficinas privadas de sanciones'],'Las OAMR prestan asistencia y digitalización en marco de registro electrónico.')
exam(6,41,'¿Qué atribución aparece como indelegable de Alcaldía en el manual?','Dirigir gobierno y Administración municipal',['Todas las tareas materiales de reparto','Toda atención de ventanilla','Toda impresión de documentos'],'El manual recoge dirección municipal entre atribuciones indelegables.')
exam(6,42,'¿Qué órgano altera la calificación jurídica de bienes de dominio público municipal en el esquema del manual?','Pleno',['Conserjería','Registro','Tesorería por decisión informal'],'Se identifica como atribución del Pleno.')
exam(6,43,'¿A quién atribuye el manual nombramiento del personal municipal y sus sanciones?','Alcaldía',['Archivo histórico','Conserjería','Registro General'],'Son funciones de Alcaldía en los términos de atribución expuestos.')
exam(6,44,'¿Mediante qué instrumento efectúa el alcalde sus delegaciones?','Decreto de Alcaldía con publicidad prevista',['Vale de préstamo','Etiqueta de archivo','Correo privado sin acto administrativo'],'El decreto es el instrumento de delegación; se publica según el marco del manual.')
exam(6,45,'¿Quién nombra y cesa libremente tenientes de alcalde entre miembros correspondientes?','El alcalde',['El subalterno de turno','Cada vecino individualmente','La Tesorería'],'El nombramiento y cese corresponde al alcalde; sustitución sigue orden establecido.')
exam(6,46,'¿Cuántas áreas de coordinación enumera el decreto organizativo de los apuntes?','Siete',['Cinco','Seis','Ocho'],'Son áreas I a VII, conservando organización del manual.')
exam(6,50,'En catástrofe, ¿quién adopta personalmente medidas urgentes y da cuenta inmediata al Pleno según manual?','El alcalde',['El archivero por iniciativa propia','Cualquier conserje sin coordinación','El registro electrónico como órgano decisor'],'Es atribución de Alcaldía en situación de necesidad.')
exam(6,51,'¿Qué materias se relacionan con cuestión de confianza municipal en los apuntes?','Presupuesto, reglamento orgánico, ordenanzas fiscales y planeamiento general',['Sólo horario de conserjería','Sólo compra de folios','Cualquier tema sin limitación'],'Se enumeran esas materias previstas; no se extiende a cualquier actuación diaria.')
exam(6,52,'¿Cuántos miembros del equipo de gobierno utiliza el tema 10 del manual?','Catorce',['Diecisiete','Veintiuno','Veintisiete'],'El Pleno tiene 27 miembros; la cifra del equipo de gobierno recogida es 14.')
exam(6,54,'¿Qué conjunto está integrado por organismos autónomos que recoge el manual?','FMM, FMC, IMD e IFEF',['PROCASA, Aguas de Cádiz y Eléctrica exclusivamente','Diputación, UCA y Hospital','Sólo empresas privadas ajenas al Ayuntamiento'],'El tema 10 enumera además Patronato del COAC; una SA no se convierte en organismo autónomo por prestar servicio público.')
exam(9,56,'¿Qué campo permite enviar copia ocultando direcciones a otros receptores?','Cco',['Cc','Asunto','Firma'],'Cco es copia oculta; Cc y Para muestran destinatarios. Se adapta la pregunta para evitar ambigüedad del enunciado antiguo.')
exam(9,57,'¿Qué dispositivo digitaliza una imagen o documento en papel?','Escáner',['Altavoz','Teclado','Proyector'],'El escáner es periférico de entrada; OCR añade reconocimiento de texto.')
exam(9,58,'¿A qué función corresponde el zoom de una fotocopiadora?','Reducción o ampliación',['Número de copias exclusivamente','Velocidad exclusivamente','Nivel de tóner exclusivamente'],'La escala modifica tamaño de reproducción; no es medida de velocidad.')
exam(9,59,'¿Qué combinación de funciones puede reunir una multifunción equipada para ello?','Copiar, imprimir, escanear y fax',['Sólo reproducir sonido','Sólo proyectar vídeo','Sólo calcular nóminas'],'Las funciones dependen del modelo; multifunción combina tareas de oficina.')
exam(9,60,'¿Qué afirmación sobre guardar imágenes escaneadas es correcta?','Hay varios formatos, como PDF, JPEG, PNG o TIFF',['Sólo existe PDF','Nunca puede guardarse imagen','Sólo puede guardarse en una hoja de cálculo'],'El formato depende de finalidad; el manual distingue varios, incluido PDF/A para conservación.')
exam(9,62,'¿Cuánto mide un A4 en centímetros?','21 × 29,7',['21 × 14,8','28 × 20','30 × 29,7'],'Equivale a 210 × 297 milímetros; invertir orientación no cambia tamaño.')
exam(8,63,'De 24 alumnos, asisten 18. ¿Qué porcentaje ha asistido?','75 %',['20 %','30 %','40 %'],'18 ÷ 24 × 100 = 75 %.')
exam(8,64,'¿Qué decimal equivale a 225/10.000?','0,0225',['0,225','2,25','0,00225'],'Dividir por 10.000 desplaza coma cuatro posiciones.')
exam(10,65,'¿Qué templo de Cádiz se conoce como Catedral Vieja?','Iglesia y parroquia de Santa Cruz',['Iglesia del Carmen','Convento de Santo Domingo','Iglesia de San Francisco'],'Santa Cruz, en El Pópulo, es Catedral Vieja; Nueva es Santa Cruz sobre el Mar.')
exam(8,66,'¿Qué frase está escrita correctamente?','A pesar de no aparecer, no se ha disculpado.',['Nadie a venido a clase.','No pude recojer a mi hermana.','Estube todo el día enfermo.'],'Se escribe ha venido, recoger y estuve; la opción correcta emplea ha como verbo.')
exam(8,67,'¿Qué palabra está correctamente acentuada?','Logístico',['Péana','Huído','Pólen'],'Logístico es esdrújula; peana, huido y polen no llevan esas tildes.')
exam(1,68,'¿Qué título de la Constitución regula su reforma?','Título X',['Título I','Título IX','Título XI'],'La reforma ocupa artículos 166–169 del título X; no hay título XI numerado.')
exam(1,69,'¿Cuándo aprobaron las Cortes Generales la Constitución de 1978?','31 de octubre de 1978',['13 de octubre de 1978','16 de diciembre de 1978','6 de diciembre de 1978'],'Aprobación por Cortes: 31 de octubre; ratificación popular: 6 de diciembre.')
exam(1,70,'¿Cómo se denomina la parte constitucional que organiza órganos del Estado?','Parte orgánica',['Parte dogmática','Parte tributaria','Parte informática'],'Parte orgánica: títulos II–X; dogmática: preliminar e I.')
exam(6,71,'Una persona consulta dónde solicitar Carnet Joven. ¿Qué servicio y sede del manual corresponden?','Juventud, Cánovas del Castillo 41',['Urbanismo, Sopranis 10','Consumo, García de Sola 12–14','FMM, Palillero'],'El supuesto oficial relaciona Juventud con Cánovas del Castillo, 41.')
exam(4,72,'¿Debe exigirse interés legítimo para informar de ubicación y requisitos generales de Carnet Joven?','No; se facilita información general sin acreditar legitimación',['Sí, siempre debe acreditar ser interesado','Sí, y presentar representación notarial','No puede informarse en ningún caso'],'La información general se ofrece a ciudadanía sin condición previa de interesado.')
exam(5,73,'Primer intento domiciliario a las 10:00 sin receptor. ¿Qué segundo intento es conforme a la regla general?','Dentro de tres días siguientes y después de 15:00, con tres horas mínimas de diferencia',['A las 11:00 del mismo día sin más','A las 10:00 una semana después','No repetir y archivar automáticamente'],'El segundo intento cambia franja horaria y se realiza una vez en plazo del artículo 42.')
exam(7,13,'¿Qué actividad no es una función legítima de un archivo?','Modificar arbitrariamente originales',['Recibir documentación','Conservar documentos','Servir información autorizada'],'Conservar integridad excluye modificar por iniciativa propia.',2024)
exam(7,14,'¿Qué declaración caracteriza a los documentos de decisión?','Voluntad del órgano en materia de su competencia',['Sólo juicio técnico sin decisión','Sólo constancia de hechos','Sólo transmisión a otra unidad'],'Decisión expresa voluntad administrativa; juicio, constancia y transmisión son clases diferentes.',2024)
exam(4,17,'¿Qué función consiste en aclarar trámites, requisitos y documentación para acceder a servicios?','Orientación e información',['Sólo custodia de llaves','Sólo mantenimiento eléctrico','Sólo recaudación tributaria'],'RD 208/1996 distingue orientación de recepción y otras funciones.',2024)
exam(6,26,'¿Qué servicio del listado se sitúa en extramuros según las sedes del manual?','Medio Ambiente en María Auxiliadora',['FMM en Palillero','Archivo en Isabel la Católica','Urbanismo en Sopranis'],'María Auxiliadora está en extramuros; las otras sedes se relacionan con casco histórico.',2024)
